import type { ReactNode } from 'react';
import { ImageBackground, StyleSheet, View, type StyleProp, type ViewStyle } from 'react-native';

import { colors } from '@/theme/tokens';

// Generated by tools/art/gen_art.py (D14). Bundled, so it works offline.
const FOREST = require('../../assets/images/bg-moonlit-forest.jpg');

interface ThemedBackgroundProps {
  children?: ReactNode;
  /** Darken the art, for screens with lots of text. */
  dim?: boolean;
  style?: StyleProp<ViewStyle>;
}

/** Full-screen moonlit-forest art behind a screen's content. */
export function ThemedBackground({ children, dim, style }: ThemedBackgroundProps) {
  return (
    <ImageBackground source={FOREST} resizeMode="cover" style={[styles.fill, style]}>
      {dim && <View style={[StyleSheet.absoluteFill, styles.dim]} pointerEvents="none" />}
      {children}
    </ImageBackground>
  );
}

const styles = StyleSheet.create({
  fill: { flex: 1, backgroundColor: colors.background },
  dim: { backgroundColor: colors.scrim },
});
